<script setup lang="ts">
import {ref} from 'vue';import PageShell from '../../components/PageShell.vue';import {usePage} from '../../composables/usePage';import {request} from '../../utils/request';const profile=ref<any>(null);const {loading,error,load}=usePage(async()=>profile.value=await request('/sitter/profile'));const days=['','周一','周二','周三','周四','周五','周六','周日']
